  border-radius: 1000px;
  padding: 0.2em 0.7em;
  background: var(--c-success);
  color: var(--c-white);
  font-size: 0.55em;
  font-weight: 800;
}

.leader__badge {
  display: inline-block;
  margin-left: 0.4em;
  border-radius: 1000px;
  padding: 0.15em 0.6em;
  background: var(--c-pink);
  color: var(--c-white);
  font-size: 0.55em;
  vertical-align: middle;
}
.leader.is-winner .leader__name::after { content: none; }
