  padding: 12px 24px;
  font-weight: 600;
  animation: flash-out 4s forwards;
  pointer-events: none;
}
.flash--alert { background: var(--c-pink); color: var(--c-white); }

@keyframes flash-out {
  0%, 80% { opacity: 1; }
